const j=$input.first().json;
if(!j.script||!j.job_id) throw new Error('script and stable job_id required');
const stages=['avatar_generation','animation_composition','caption_timing','encode','ffprobe_qa'];
const s=Number(j.resume_stage||0); if(!Number.isInteger(s)||s<0||s>stages.length) throw new Error('resume_stage out of range');
return [{json:{job_id:j.job_id,idempotency_key:'avatar:'+j.job_id,script:j.script,stages:stages.map((name,i)=>({name,status:i<s?'complete':i===s?'ready_for_worker':'blocked',worker_contract:'PENDING; use a versioned local adapter'})),render_status:'pending_worker',output_validation:['video_stream_present','audio_or_intentional_silence','captions_readable','duration_within_limit'],external_publish:false}}];
